    "v0.22.318：本次更新｜财务按事项分区办理、付款与费用分离、步骤简化和月报资料状态纠正。",
    "v0.22.317：本次更新｜供应商付款三步简化，收货明细折叠、中文计价单位、草稿无误导零值。",
    "v0.22.316：本次更新｜供应商到期草稿后台自动生成、改期重算当月草稿；保留历史版本与确认付款门禁。",
    "v0.22.316：如何验证｜修改供应商对账日，核对当月草稿周期与明细新版本；无实收时金额为零。",
    "v0.22.314：本次更新｜客户成品规格与供应商外购规格分离；标签和送货按有效客户冻结规格，缺失时按冻结客户品名明确尺寸回退。",
    "v0.22.315：本次更新｜供应商付款默认先抵扣已登记的同供应商余额，再计算银行补差；不新增承兑选票或拒收功能。",
    "v0.22.315：如何验证｜打开有余额的待付款月结，核对抵扣金额与银行差额；确认前不生成付款，发票及版本门禁保持不变。",
