    "v0.22.106：本次更新｜仓库地图日常区域规划简化为选择主要用途、栈板区或货架区、最大栈板数，再一次确认启用；保存、校验、发布和容量确认由系统受控完成，高级边界与货架工具默认收起。",
    "v0.22.106：本次更新｜点击货物或区域后的右栏只先显示位置/区域、状态、客户、数量、栈板或库存记录等核心结果；批次、内部码、库龄、预占和位置栈板详情按需展开，多条库存保留查看全部。",
