    "v0.22.106：如何验证｜在查货模式分别点击一个有货位置和一个区域，确认右栏先显示核心摘要；“位置与栈板详情”“批次与预占详情”和“查看全部”仍能打开完整事实，空区域继续显示真实空态。",
    "v0.22.106：如何验证｜进入“系统备份 → 系统版本”确认显示 v0.22.106、数据库 revision 仍为 mm21v8x9z10；发布过程本身不得归档区域、移动栈板、生成模拟货物或改写库存数量。",
    "v0.22.105：本次更新｜“仓库 → 模具与位置查询”的状态栏新增“已打印/未打印”提醒；单件或批量打印登记成功后，刷新列表即可看到打印状态。",
