    "v0.22.105：如何验证｜进入“系统备份 → 系统版本”确认显示 v0.22.105、数据库 revision 为 mm21v8x9z10；发布本身不得自动打印、回填历史打印状态或改写模具位置。",
    "v0.22.104：本次更新｜模具标签继续使用40×30毫米黑白纸型，取消外围框和位置字段；针对当前标签机实打整体右偏约2毫米，打印内容向左补偿2毫米，固定二维码在右下方并向下约2毫米。",
