    "v0.22.104：如何验证｜使用 Gprinter 40×30毫米、203dpi、缩放100%、无边距并关闭浏览器页眉页脚打印一张，核对整体不再右偏、二维码向下约2毫米、客户名和不同长度编号清晰完整且不与二维码重叠。",
    "v0.22.104：如何验证｜用手机扫描固定二维码，确认仍进入同一模具实时页；登录后订单、收料和材料位置按现有权限实时显示，标签排版调整没有改变二维码身份或业务状态。",
    "v0.22.104：如何验证｜进入“系统备份 → 系统版本”确认显示 v0.22.104、数据库 revision 仍为 ll20v8x9z09；发布过程不得改写模具、订单、收料、库存或库位事实。",
    "v0.22.103：本次更新｜实测地图未绑定的区域不再误显示容量复核入口；先在当前区域设置中明确选择同楼层、未绑定且没有正式库位的现有区域，或建立新区域草稿。",
    "v0.22.103：本次更新｜已正式绑定但容量待复核的区域，前往容量复核时会同时核对正式区域、楼层、区域编号和地图区域身份；缺失、漂移或未发布时失败关闭，不会打开另一块区域。",
    "v0.22.103：本次更新｜选用现有区域后，正式区域与楼层身份写入地图草稿，并在保存、校验和发布时重复核对；发布复用同一正式区域，不新建第二条同码区域，也不搬运或补写库存。",
    "v0.22.103：本次更新｜当前区域没有真实库存时继续显示真实空态，不生成模拟货物或栈板；本版不新增数据库迁移，也不自动把现有 A2 猜绑到任何原料区。",
