    "v0.22.102：如何验证｜只修改备注并保存，确认位置和位置版本不变，模具详情时间线不新增移动流水。",
    "v0.22.102：如何验证｜仅在模具实物确实从货架第2层搬到第3层后选择对应新位置；核对原位置与新位置并确认，刷新后列表、详情和标签显示新位置且只新增一条移动流水。",
    "v0.22.102：如何验证｜进入“系统备份 → 系统版本”确认显示 v0.22.102、数据库 revision 仍为 ll20v8x9z09；未真实搬动模具时不得为了验收修改正式位置。",
    "v0.22.101：本次更新｜已有成品库存覆盖的订单，剩余纸板实收按真实物理投入生成生产计划，不再重复扣减成品覆盖；订单50只、成品覆盖30只、实收20张时，正确待生产20只。",
