    "v0.22.100：如何验证｜进入“系统备份 → 系统版本”确认显示 v0.22.100、数据库 revision 仍为 ll20v8x9z09；发布过程不得改写正式业务事实。",
    "v0.22.99：本次更新｜外购包材采购零实收时，订单撤回或废弃会同步生成可审计取消事实并退出待收料；已有部分或全部实收时明确阻止，不删除或篡改采购、实收及库存历史。",
