    "v0.22.99：本次更新｜已取消采购不能继续确认、收料或打印；待送货、新建送货单和正式发货统一校验包材收齐，历史组合套件送货草稿也不能绕过。",
    "v0.22.99：本次更新｜本版迁移为 kk19→ll20 单 head，只新增不可变的采购取消事实结构，不批量推断或回填历史；另按老板授权精确修复一条已核验的现场零实收异常。",
