    "v0.22.99：如何验证｜在没有任何实收时撤回并废弃订单，确认对应 EP 单从外购包装待收消失、时间线保留取消事实；重复撤回、废弃和刷新不得新增重复日志。",
    "v0.22.99：如何验证｜另用一单验证部分实收后撤回或废弃会被阻止；纯外购收齐后直接待送货，混合 BOM 必须两路收齐并完成生产后才可送货。",
