    "v0.22.98：本次更新｜仓库实测地图支持权限受控的整板移货、待送多栈逐板选择和同客户栈板一次合并；草稿先预览，确认后整批事务提交，失败整体回滚。",
    "v0.22.98：本次更新｜来料生产卡独立打开、常用箱包装标签策略保存与 40×30 标签计划/模板形成可审计链，历史模板不被日期或状态猜测补造。",
    "v0.22.98：本次更新｜常用箱直接印刷颜色与挂板行按正式主数据保存；生产任务首次创建冻结颜色、挂板编号/名称/内容和机器参数，后续主档变化不覆盖历史快照。",
    "v0.22.98：本次更新｜外购包装采购单的供应商打印版只显示采购双方、采购单号、日期、规格和数量/单位，不再向供应商展示任何客户、客户订单、产品或图纸信息。",
