    "v0.22.15：打印内容按实际页面高度自动分页；每页重复显示天明包装抬头、客户信息、当页明细、签收栏和总页码，长产品名称允许自动换行。",
    "v0.22.15：系统备份页增加送货单打印纸张宽高配置；默认值和异常回退均为 241×139.5mm，保存仅限管理员并保留审计记录，本次不新增数据库迁移。",
    "v0.22.14：订单 PDF 单份预览、批量预览和人工重匹配统一执行客户范围门禁；受限账号只会匹配已授权客户，空范围或跨客户结果在查询常用箱候选前按拒绝处理。",
    "v0.22.14：旧版天华、高泰和思迈尔无模板客户 ID 的专项路由继续兼容，但必须能在当前账号允许的客户集合内唯一确认，否则保持人工确认且不返回跨客户业务数据。",
    "v0.22.14：PDF 草稿响应统一按 cost.view 权限脱敏；未授权账号看不到成本、毛利和供应商报价，仍可查看 PDF 客户单价、常用箱销售价、产品名称、规格和匹配证据。",
    "v0.22.13：启用状态的通用客户 PDF 模板可在训练库重新解析和订单预览中执行订单号、日期、明细行及字段映射规则；支持命名捕获组和旧版数字捕获组映射。",
    "v0.22.13：天华、高泰、思迈尔继续优先使用专项解析器，宽泛通用模板不能抢占专项客户；草稿和已退役模板不会进入正式解析。",
    "v0.22.13：模板保存和运行均校验正则安全结构、字段映射、捕获组、文本长度和明细上限；用户正则由独立子进程限时限量执行，异常只进入人工确认，不静默回退或自动写订单。",
    "v0.22.13：通用模板只有在原文明细行独立核对一致、唯一整单合计位于最后明细之后且数量金额一致时才通过完整性校验；分页小计、多合计或无合计均保持人工确认。",
    "v0.22.12：PDF 预览保存采用签名安全令牌和完整性门禁；客户路由、来源文件、人工确认与产品归属均由后端再次校验，识别结果仍只进入草稿，不会自动写正式订单。",
    "v0.22.12：PDF 客户模板支持启用、停用、版本替换和唯一生效规则；训练样本增加黄金复核状态，旧模板和旧样本不自动污染新解析结果。",
    "v0.22.12：权限配置、客户范围和组合访问保存均写入可追溯审计；并发修改使用认证版本乐观锁，过期页面返回 409，不会覆盖其他管理员的新配置。",
    "v0.22.12：客户范围权限扩展到报料、供应商采购、补库、历史采购、成品与半成品库存、库存洞察和三楼栈板；空范围、直接 ID、混合客户及异常跨客户绑定均按拒绝处理。",
    "v0.22.12：没有成本查看权限的账号只能看到库龄、数量、库位和需求等运营信息；成本金额、来源、覆盖率和成本原因由后端白名单脱敏，未知嵌套字段默认不返回。",
    "v0.22.12：正式数据库已在迁移前完成在线备份和完整性检查，并线性升级到 bc56v8x9z46；迁移后 integrity_check 正常、外键异常为 0。",
    "v0.22.11：生产环境启用安全 Cookie、HTTPS 跳转、HSTS、可信主机、显式 HTTPS 跨域来源与受信代理配置；默认仅监听本机并要求强会话密钥，未自动开放公网端口、修改路由器或申请证书。",
    "v0.22.11：公开健康检查只返回最小可用状态；精确版本、构建日期和完整更新日志均须登录后读取。",
    "v0.22.11：会话令牌加入账号认证版本；退出登录、修改密码、停用账号、调整角色权限或客户范围后，旧会话立即失效。",
    "v0.22.11：同一用户名与来源地址在 15 分钟内连续登录失败 5 次后限流；失败与限流写入安全审计，但不会记录密码或影响同一网络内的其他账号。",
    "v0.22.11：新增认证版本线性迁移并仅在隔离数据库副本完成升级与降级保护演练；本阶段未迁移或写入正式数据库。",
    "v0.22.10：订单日期、报料日期、库存日期和各类今日统计统一按北京时间（UTC+8）判断，凌晨 00:00 至 07:59 不再误算到前一天。",
    "v0.22.10：新产生的审计时间统一使用 UTC 保存，接口返回明确携带 Z 或 +08:00；历史上按北京时间保存的少数字段保留原语义，不批量改写历史记录。",
    "v0.22.10：仓库、来料、送货、报料、生产、PDF 训练和系统备份的时间显示统一转换为北京时间，日期字段继续保持 YYYY-MM-DD 业务日期。",
    "v0.22.10：北京时间日期筛选使用半开 UTC 边界，避免跨日漏查或重复；本次不新增数据库迁移。",
    "v0.22.9：老板账号默认使用大字模式，所有账号均可在顶部切换标准/大字显示；选择结果保存到账号，下次登录继续沿用。",
    "v0.22.9：大字模式统一放大正文、标题、标签、按钮和输入框，并针对常用屏幕与系统缩放优化响应式布局。",
    "v0.22.9：老板首页聚焦待报料、待入库、待送货、应收、库存风险和经营异常六项业务信息，不显示技术维护入口和敏感成本明细。",
    "v0.22.8：客户、常用箱和材质主数据建立版本历史快照，记录字段修改原因与操作者，支持按版本追溯。",
    "v0.22.8：主数据写入执行版本校验与事务保护，发现并发冲突返回 409；异常变更需二次确认，历史记录不可改写。",
    "v0.22.8：管理员恢复历史版本会以新版本写入，并记录恢复来源与恢复原因，避免覆盖原有历史。",
    "v0.22.8：产品成本/板价、材质报价及供应商价格等敏感价格按权限展示，未授权历史查询自动脱敏。",
    "v0.22.7：新增轻量生产完工工作台；来料就绪后进入待完工，员工可按同一客户批量确认直接送货或转入 F12/F34 临时成品库。",
    "v0.22.7：生产完工、转库存、发货、订单终止和流程撤回使用共享并发锁与幂等校验；真实发货、终态订单和已有生产事实均会被后端再次拦截。",
    "v0.22.7：成品与半成品库存避免重复预占；半成品批次可限定客户并绑定多个允许款号，未绑定允许款号的客户专用批次不能参与抵扣。",
    "v0.22.7：供应商材质与业务明细支持七层纸板；七层材质代码必须为 7 位，楞型由人工选择 AAA 或 ABC，不设置默认值。",
    "v0.22.6：订单管理与 PDF 训练库接入思迈尔专用混合解析；自定义字体文本层保留客户单号、数量、单价、金额和日期，OCR 只补产品名称与规格。",
    "v0.22.6：思迈尔相同 CPN 存货编码的多行明细不再合并；产品匹配同时参考供应商变体编码、产品名称、规格和 PDF 单价，存在歧义时继续要求人工选择。",
    "v0.22.6：增加思迈尔行数与金额完整性校验，并修复小字号 OCR 可能把 13211 误读成 1321 的假异常；12 份现场样本共 61 行全部保留且金额合计一致。",
    "v0.22.6：训练库人工标注会生成字段级纠错候选；新增只读审计脚本，仅输出重复样本和模板的 dry-run 清单，不删除数据、不创建正式订单。",
    "v0.22.5：成品库存批次统一通过“编辑”弹窗修改；支持客户专用与通用库存双向切换、按客户重新匹配存货编码、修改可用数量、三楼货位和入库日期。库龄统一由入库日期计算；已有预占或消耗的批次仍可改数量、货位和日期，但会保护产品与客户归属不被改错。所有修改保留库存流水和并发校验。",
    "v0.22.5：成品仓库存列表无需横向滚动；批次最多两行，客户最多两行，材质与楞型固定各一行，操作只保留编辑和转通用并贴齐右侧。表头支持像 Excel 一样拖动相邻列宽，设置保存在当前浏览器，双击分隔线可恢复默认。",
    "v0.22.5：入成品仓支持先选择客户，再输入存货编码或产品名称实时匹配候选；候选同时显示产品名称和规格，并且必须人工点选确认，不再翻找整张常用箱长下拉。",
    "v0.22.5：成品做好后可直接送货；只有需要暂存时才办理一次“入成品仓”，日常操作不再要求重复登记。",
    "v0.22.5：入成品仓只需选择客户、产品、数量和三楼具体货位，系统在同一事务中自动建立正式库存、真实栈板绑定和库存流水。",
    "v0.22.5：正式成品库存是唯一数量账；三楼平面图实时读取该库存余额，移动栈板会同步更新正式库存货位，现场盘点快照不会冒充正式库存。",
    "v0.22.5：半成品仓与补库流程继续使用原有专用库位，本次未改变订单、报料、送货或对账数量口径。",
    "v0.22.4：修复区域布局拖动后无法准确拖回原位的问题；拖拽保留鼠标抓取偏移并按货位尺寸限制边界，另提供撤销本区未保存调整。",
    "v0.22.4：E4 全局图保持左侧货架位置，右侧两列栈板向右展开至接近 AB2 宽度，允许占用现场死角区域。",
    "v0.22.4：三楼仓库升级为左侧区域导航、中间真实比例画布、右侧货位详情的可视化库存工作区，既有坐标、尺寸和编号保持不变。",
    "v0.22.4：新增客户、区域、占用状态和关键词组合筛选；搜索结果可定位并高亮货位，输入请求增加防抖和过期响应保护。",
    "v0.22.4：浏览模式与库位调整模式明确分离；浏览模式不能移动栈板，调整模式显示醒目提示并继续使用确认、权限、版本冲突和失败刷新保护。",
    "v0.22.4：仓库画布支持适应窗口、恢复默认、按钮或滚轮缩放、放大后空白处平移、图例折叠和全屏查看。",
    "v0.22.4：本次交互升级复用现有真实货位、栈板、物料和操作记录，没有新增迁移，也没有把三楼快照自动写入正式订单、报料、来料、库存或送货数量。",
    "v0.22.3：三楼货位 Phase A 只记录货位、真实栈板和盘点内容，不会自动改变订单、报料、来料、正式库存或送货数量。",
    "v0.22.3：三楼全图的区域入口统一移到相邻通道，区域轮廓不再接收点击，避免遮挡底部栈板和货架格。",
    "v0.22.3：D1 区按现场结构显示为二层一排货架、底部两排栈板，每个货架格和栈板位均可独立查看。",
    "v0.22.3：E4 区改为左侧一列货架、右侧两列栈板（每列 6 位）；DE1 区栈板按现场方向纵向显示。",
    "v0.22.3：F2、F3、F4 三个三层货架统一等宽等高显示，F12、F34 继续位于 F1 下方作为过道临放位。",
    "v0.22.3：三楼平面图采用横向满版显示，F1/F2/F3/F4/F12/F34 合并为一个 F 区入口，A 至 E 区位置关系更醒目。",
    "v0.22.3：100% 缩放可在单页完整查看 396 个预设货位；页面、全图和 F 区货架均不产生横向滚动。",
    "v0.22.3：只有点击区域标识才进入区域放大；点击具体货位保持全图，并在固定右栏显示客户、存货编码、产品名称、数量和款式数。",
    "v0.22.3：F 区使用立体货架视图，F1 分底部栈板和二层物料，F2/F3/F4 按三层货架显示并可逐格查看详情。",
    "v0.22.3：F2、F3、F4 货架格只登记和查看物料，不作为底部栈板位；真实栈板仅可在空地面位或 F12/F34 临放位间安全移动。",
    "v0.22.3：管理员可新增、停用或恢复实际货位，布局变化不会修改库存数量，并保留并发版本校验和移动记录。",
    "v0.22.2：月结对账改为按整张送货单选择，同一张送货单的全部明细统一进入同一份对账单。",
    "v0.22.2：客户可配置月结结转日，默认每月 20 日，并按送货日期自动划分对账周期。",
    "v0.22.2：历史上已被部分对账的送货单会明确标记并禁止再次拆分选择，避免重复或漏对账。",
    "v0.20.8：常用箱编辑页面压缩为五排，长宽高、报料尺寸和压线信息集中在第二排。",
    "v0.20.8：A1/0201 普通开槽箱会按采购经验自动推荐报料长宽，使用整体 30mm 搭口和宽度方向 5mm 放量。",
    "v0.20.8：选择压线后自动推荐上摇盖、高、下摇盖；手工修改后的尺寸不会被系统覆盖。",
    "v0.20.8：其他箱型已加入列表，暂无可靠公式的箱型会明确提示人工填写。",
    "v0.20.8：长、宽、高按整数毫米显示，单价仍保留小数。",
    "v0.20.8：生产工艺可以同时选择粘贴、打钉、模切、双拼或其他。",
    "v0.20.8：印刷内容改为明确选项，无印刷时自动隐藏图纸区域。",
    "v0.20.8：有印刷的常用箱可以继续上传新图纸，并按时间查看历史版本。",
    "v0.20.8：报料长宽、压线类型、A1推荐计算和报料备注在桌面上保持同一行。",
    "v0.20.7：首页待对账提醒现在按客户+月份汇总，同一个客户同一个月只显示一条。",
    "v0.20.7：首页待对账卡片和待办更清楚了，管理员一眼就能看出哪一户、哪一个月该处理。",
    "v0.20.7：新增一键启动脚本，双击桌面图标就能自动升级、启动 ERP 并打开网页。",
    "v0.20.7：新增停止脚本、桌面快捷方式和开机自启脚本，普通操作员更容易上手。",
    "v0.20.6：首页现在一打开就能看到待报料、待入库、待送货、待回单、待对账和未结清这些待办。",
    "v0.20.6：首页多了一块大字卡片和待办列表，管理员一眼就知道先处理什么。",
    "v0.20.6：首页加载失败时会显示中文提示，不会空白。",
    "v0.20.6：保留原来的业绩摘要，方便继续看今天和本月的大概情况。",
    "v0.17.1：修正楞型业务规则（A/B/E 均为三层单楞，AB/BE 为五层双楞）",
    "v0.17.1：新增歧义楞型检测（B/E、A4B-B/E 等不自动写入）",
